function flowMarkup(flow,index){const width=(Math.max(...flow.nodes.map(n=>n[1]))+1)*110-20,height=(Math.max(...flow.nodes.map(n=>n[2]))+1)*210-10,id='flow-'+index;const lines=flow.edges.map(([from,to,label])=>{const a=flow.nodes.find(n=>n[0]===from),b=flow.nodes.find(n=>n[0]===to);const sameRow=a[2]===b[2],down=b[2]>a[2];const x1=a[1]*110+(sameRow?76:37),y1=a[2]*210+(sameRow?75:down?174:0),x2=b[1]*110+(sameRow?-4:37),y2=b[2]*210+(sameRow?75:down?-7:180);const path=sameRow?`M${x1} ${y1}H${x2}`:`M${x1} ${y1}V${(y1+y2)/2}H${x2}V${y2}`;return `<path d="${path}"><title>${E(label)}</title></path>`}).join('');return `<section class="flowJourney"><h3>${E(flow.title)}</h3><div class="coverageGraph" style="width:${width}px;height:${height}px"><svg width="${width}" height="${height}" aria-label="Journey connections"><defs><marker id="${id}" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><path d="M0 0L7 3.5L0 7" fill="#80916f"/></marker></defs><g fill="none" stroke="#80916f" stroke-width="1.4" marker-end="url(#${id})">${lines}</g></svg>${flow.nodes.map(([key,col,row])=>{const s=scenarios.find(s=>s.key===key);return `<article class="scenarioTile" style="left:${col*110}px;top:${row*210}px" data-scenario="${key}"><button onclick="startScenario('${key}')" aria-label="Try scenario: ${E(s.title)}"><img class="slice-image" src="scenarios-09/${key}.jpg" width="390" height="780" alt=""><h2>${E(s.title)}</h2></button></article>`}).join('')}</div></section>`}
function markSelected(){document.querySelectorAll('[data-scenario]').forEach(e=>e.setAttribute('aria-current',String(e.dataset.scenario===activeScenario)))}
function instructions(){const s=scenarios.find(s=>s.key===activeScenario);document.getElementById('scenarioTitle').innerHTML=`${E(s.title)} <span class="coverageCount">${scenarios.length} scenarios</span>`;for(const[id,label,text]of[['scenarioSituation','Situation',s.situation],['scenarioAction','Try',s.action],['scenarioExpected','Expected',s.expected],['scenarioStatus','Design status',s.status]])document.getElementById(id).innerHTML=`<b>${label}: </b>${E(text)}`;markSelected()}
function go(next){backStack.push(view);view=next;drawer=false;sheet='';state.providerMenu=false;render()}
function back(){if(sheet){sheet='';render();return}if(drawer){drawer=false;render();return}if(state.providerMenu){state.providerMenu=false;render();return}if(state.keyboard){state.keyboard=false;render();return}view=backStack.pop()||'chat';render()}
function openDrawer(){drawer=true;render()}
function button(label,code,primary=false){return `<button type="button" ${primary?'class="primary"':''} onclick="${E(code)}">${E(label)}</button>`}
function actions(...buttons){return `<div class="actionStack">${buttons.join('')}</div>`}
function info(text,error=false){return `<div class="infoBox ${error?'errorBox':''}" role="status">${E(text)}</div>`}
function field(label,id,value='',type='text'){return `<label class="demoField">${E(label)}<input id="${id}" type="${type}" value="${E(state.form[id]??value)}" oninput="state.form['${id}']=this.value" autocomplete="off"></label>`}
function screen(title,body,system=false){return `<div class="screenContent entering ${system?'systemScreen':''}">${system?'<div class="stepHint">Android system · simulated</div>':''}<h2>${E(title)}</h2>${body}</div>`}
function row(title,detail,code,status=''){return `<button class="choiceRow" onclick="${E(code)}"><span>${E(title)}<small>${E(detail)}</small></span>${status?chip(status):'›'}</button>`}
function chip(status){return `<span class="stateChip ${status}">${E({needs:'Needs you',working:'Working',done:'Done',error:'Error',stopped:'Stopped',ready:'Ready',off:'Not set up'}[status]||status)}</span>`}
function header(){const title=state.onboarding?'Set up Olea':view==='chat'||view==='draft'?(state.current===null?'New conversation':currentSession().title):['terminal','terminal-switch','terminal-running','terminal-close'].includes(view)?state.workspace+' · Terminal':({history:'Conversations',workspaces:'Workspaces',terminal:'Olea · Terminal','terminal-running':'Olea · Terminal','terminal-switch':'Olea · Terminal'}[view]||scenarios.find(s=>s.key===view)?.title||'Olea');const root=['chat','draft','history','workspaces'].includes(view)&&!state.onboarding;return `<div class="apphead">${button(root?'☰':'‹',root?'openDrawer()':'back()')}<div class="title"><strong>${E(title)}</strong>${!state.onboarding&&(view==='chat'||view==='draft')&&state.current!==null?`<small>${E(currentSession().agent)} · ${E(currentSession().workspace)}</small>`:''}</div>${!state.onboarding?button('＋','newChat()')+button('⋯',"sheet='details';render()") :''}</div>`}
function newChat(){state.current=null;state.draft='';state.draftAgent='';state.workspace=state.filter==='All workspaces'?'Personal':state.filter;go('draft')}
function send(){const text=state.draft.trim();if(!text||!state.environment)return;let setup;
 if(state.current===null){
  if(!state.draftAgent){state.notice='Choose an agent before sending.';render();return}
  setup=document.querySelector('.sessionSetup');
  const s={id:Math.max(...state.sessions.map(s=>s.id))+1,title:text.slice(0,38),agent:state.draftAgent,provider:state.draftProvider,workspace:state.workspace,status:'working',messages:[['user',text],['agent','I’ll inspect the workspace files first.']]};state.sessions.push(s);state.current=state.last=s.id;
 }else{const s=currentSession();if(s.status==='working')return;s.messages.push(['user',text],['agent','I’ll inspect the relevant context.']);s.status='working'}
 state.draft='';state.notice='';state.keyboard=false;state.providerMenu=false;view='chat';render();
 if(setup&&!matchMedia('(prefers-reduced-motion: reduce)').matches){setup.classList.add('leaving');setup.inert=true;setup.setAttribute('aria-hidden','true');setup.querySelectorAll('[id]').forEach(e=>e.removeAttribute('id'));document.querySelector('.composerDock').prepend(setup);setup.addEventListener('animationend',()=>setup.remove(),{once:true})}
}
function stop(){if(currentSession().status==='working'){currentSession().status='stopped';currentSession().messages.push(['agent','Turn stopped. Review the last tool result before continuing.']);view='chat';render()}}
function finish(){if(state.current!==null&&currentSession().status==='working'){currentSession().status='done';currentSession().messages.push(['agent','This turn is complete. The reading view is ready for your review.']);view='chat';render()}}
function fail(){if(state.current!==null&&currentSession().status==='working'){currentSession().status='error';view='error';render()}}
function reopen(){drawer=false;sheet='';state.keyboard=false;backStack=[];if(state.onboarding){state.setupResumeView=view;view='setup-resume';render();return}if(state.launch==='fresh')newChat();else{state.current=state.last;view=state.environment?'chat':'environment-lost';render()}}
function openSession(id){state.current=state.last=id;state.workspace=currentSession().workspace;state.draft='';go('chat')}
function selectWorkspace(name){state.workspace=name;state.filter=name;go('history')}
function answer(text){currentSession().messages.push(['user',text],['agent','I’ll inspect that next.']);currentSession().status='working';view='chat';render()}
function tools(){const status=currentSession().status;return `<details class="tools"><summary>${status==='working'?'Reading files…':'Workspace read'} · read</summary><pre>projects/reading-view.md\nprojects/login-redirect.md\n\n${status==='working'?'Reading project context…':'Last result preserved in this sample.'}</pre></details>`}
function keyboard(){return `<div class="keyboard" aria-label="Simulated phone keyboard">${['qwertyuiop','asdfghjkl','zxcvbnm'].map(letters=>`<div class="keyrow">${[...letters].map(c=>button(c,`typeKey('${c}')`)).join('')}</div>`).join('')}<div class="keyrow">${button('⌫',"typeKey('Backspace')")}${button('space',"typeKey(' ')")}${button('Hide','state.keyboard=false;render()')}</div></div>`}
function typeKey(k){if(isTerminal()&&state.ctrl&&k.toLowerCase()==='c'){interruptShell();return}if(isTerminal()){const input=document.getElementById('terminalCommand');state.form.command=k==='Backspace'?(state.form.command||'').slice(0,-1):(state.form.command||'')+k;input.value=state.form.command;return}state.draft=k==='Backspace'?state.draft.slice(0,-1):state.draft+k;const input=document.getElementById('messageInput');if(input)input.value=state.draft}
function providerMenu(){const selected=state.current===null?state.draftProvider:currentSession().provider||'Sample connection';return `<section class="composerPopover providerPopup" id="providerMenu" role="dialog" aria-label="Provider menu"><h3>Provider</h3>${state.connections.map(name=>`<button type="button" class="providerChoice" aria-pressed="${name===selected}" onclick="${E(`selectProvider(${JSON.stringify(name)})`)}"><span>${E(name)}</span><span aria-hidden="true">${name===selected?'✓':''}</span></button>`).join('')}<button type="button" class="manageProviders" onclick="go('providers')">Manage providers ›</button></section>`}
function selectProvider(name){if(state.current===null)state.draftProvider=name;else currentSession().provider=name;state.providerMenu=false;render();document.getElementById('providerToggle')?.focus()}
function chat(){const draft=state.current===null,s=currentSession();const stateUI=draft?'':chip(s.status);const needs=!draft&&s.status==='needs'?`<div class="chatNotice needs"><b>Needs you</b><p>Which area should I inspect?</p>${button('Review the login fix',"answer('Review the login fix')")}${button('Review the reading view',"answer('Review the reading view')")}</div>`:'';return `<div class="body entering" id="messageBody">${draft?`<div class="empty" style="flex-direction:column"><h2>What’s on your mind?</h2>${state.notice?info(state.notice):''}${!state.environment?info('Start the environment before sending.'):''}</div>`:`<div class="messages">${s.messages.map(([role,text])=>`<div class="${role}">${E(text)}</div>`).join('')}${tools()}${stateUI}${needs}${s.status==='stopped'?info('Turn stopped. The environment remains available.'):''}${state.notice?info(state.notice):''}${!state.environment?info('Environment unavailable. Start it from the app menu before sending.'):''}</div>`}</div><div class="composerDock">${draft?`<section class="composerPopover sessionSetup" aria-label="New session setup"><div class="setup"><label>Workspace<select onchange="state.workspace=this.value">${state.workspaces.map(w=>`<option ${w===state.workspace?'selected':''}>${E(w)}</option>`).join('')}</select></label><label>Agent<select id="agentSelect" onchange="state.draftAgent=this.value"><option value="">Choose agent</option>${['Pi','Codex','Claude Code'].map(a=>`<option ${a===state.draftAgent?'selected':''}>${a}</option>`).join('')}</select></label></div></section>`:''}${state.providerMenu?providerMenu():''}<form class="composer" onsubmit="event.preventDefault();send()"><textarea id="messageInput" aria-label="Message" placeholder="${draft?'Ask anything…':'Message '+E(s.agent)+'…'}" oninput="state.draft=this.value">${E(state.draft)}</textarea><div class="composeactions"><button type="button" id="providerToggle" aria-haspopup="dialog" aria-expanded="${state.providerMenu}" ${state.providerMenu?'aria-controls="providerMenu"':''} onclick="state.providerMenu=!state.providerMenu;render();if(state.providerMenu)document.querySelector('#providerMenu button').focus()">Provider <span aria-hidden="true">⌄</span></button>${!draft&&s.status==='working'?'<button class="stop" type="button" onclick="stop()">■ Stop turn</button>':'<button class="primary" type="submit">↑ Send</button>'}</div></form></div>${state.keyboard?keyboard():''}`}
function historyView(){const list=state.sessions.filter(s=>(state.filter==='All workspaces'||s.workspace===state.filter)&&(`${s.title} ${s.workspace} ${s.agent}`).toLowerCase().includes(state.search.toLowerCase()));return screen('Conversations',`<label class="demoField">Workspace<select id="historyFilter" onchange="state.filter=this.value;render()">${['All workspaces',...state.workspaces].map(w=>`<option ${state.filter===w?'selected':''}>${E(w)}</option>`).join('')}</select></label><input class="search" style="margin:8px 0;width:100%" aria-label="Search conversations" value="${E(state.search)}" placeholder="Search conversations" oninput="state.search=this.value;updateHistoryResults()"><div id="historyResults">${historyRows(list)}</div>`)}
function historyRows(list){return list.map(s=>row(s.title,`${state.filter==='All workspaces'?s.workspace+' · ':''}${s.agent}`,`openSession(${s.id})`,s.status)).join('')||`<p>No conversations in this view.</p>${actions(button('New conversation','newChat()',true))}`}
function updateHistoryResults(){const list=state.sessions.filter(s=>(state.filter==='All workspaces'||s.workspace===state.filter)&&(`${s.title} ${s.workspace} ${s.agent}`).toLowerCase().includes(state.search.toLowerCase()));document.getElementById('historyResults').innerHTML=historyRows(list)}
function createWorkspace(){const name=(state.form.workspaceName||'New project').trim();if(!name)return;if(!state.workspaces.includes(name))state.workspaces.push(name);state.workspace=state.filter=name;if(state.onboarding)go('setup-access');else go('history')}
function setupBody(){switch(view){case'welcome':return screen('Your agents. On your phone.',`<p>Prepare Olea, choose an agent and set up a workspace before your first task.</p>${info('Pi · Codex · Claude Code')}${actions(button('Get started',"go('prepare')",true))}`);case'prepare':return screen('Prepare environment',`<div class="stepHint">Setup · Environment</div><p>Set up the local Linux environment and shared tools.</p>${state.prepared?info('Environment ready'):info('Ready to prepare')}${actions(button(state.prepared?'Continue':'Prepare environment',state.prepared?"go('choose-agent')":"state.prepared=true;render()",true),button('View sample failure',"go('setup-error')"))}`);case'setup-error':return screen('Preparation interrupted',info('The sample download could not finish. Your completed setup steps are kept.',true)+actions(button('Retry preparation',"state.prepared=true;go('prepare')",true)));case'choose-agent':return screen('Choose your agent',`<p>Choose one to set up now. You can add the others later.</p>${['Pi','Codex','Claude Code'].map(a=>row(a,state.setupAgent===a?'Selected':'Install and configure',`state.setupAgent='${a}';render()`,state.setupAgent===a?'Selected':'')).join('')}${actions(button('Install selected agent',"installAgent()",true))}${state.notice?info(state.notice):''}`);case'agent-install-error':return screen('Installation failed',info('Could not install the selected agent. Environment preparation is kept.',true)+actions(button('Retry installation',"state.installed=true;go('configure')",true)));case'configure':case'agent-config':return connectionScreen();case'auth-error':return screen('Connection needs attention',info('The sample credentials were rejected. Nothing was sent to a real provider.',true)+actions(button('Edit connection',"go('configure')",true)));case'setup-workspace':case'create-workspace':return screen('Create a workspace',`<p>Keep a project’s conversations and files together.</p>${field('Workspace name','workspaceName','New project')}${actions(button('Create workspace','createWorkspace()',true),button('Connect existing Android folder',"go('external-folder')"))}`);case'setup-access':return capabilityScreen(true);case'ready':return screen('You’re ready',`<p>Your chosen agent and workspace are ready to use.</p>${info(`${state.setupAgent||'Pi'} · Environment ready · ${state.workspace}`)}${info('Optional phone capabilities can be enabled later.')}${actions(button('Open Conversations',"state.onboarding=false;state.setupDone=true;state.filter='All workspaces';go('history')",true))}`);case'setup-resume':return screen('Continue setting up Olea',`<p>Your progress has been kept.</p>${info(state.prepared?'Environment · Ready':'Environment · Not prepared')}${info(state.setupAgent?'Agent · '+state.setupAgent:'Agent · Not yet chosen')}${actions(button('Continue setup',"go(state.setupResumeView||(state.prepared?'choose-agent':'prepare'))",true))}`);case'chat':case'draft':return null;default:return null}}
function installAgent(){if(!state.setupAgent){state.notice='Choose an agent to install.';render();return}state.agent=state.setupAgent;state.installed=true;state.notice='';go('configure')}
function connectionScreen(){const agent=state.onboarding?(state.setupAgent||'Pi'):state.agent;return screen(`Configure ${agent}`,`<p>${agent==='Pi'?'Connect this agent to a sample provider.':agent==='Codex'?'Choose a provider connection or the agent’s own login flow.':'Use Claude Code’s own authentication or a supported connection.'}</p><label class="demoField">Connection method<select onchange="state.form.auth=this.value"><option>Sample provider connection</option><option>Agent login</option></select></label>${field('Display name','connectionName','Sample connection')}${info('Demo uses a fictitious connection. Do not enter real credentials here.')}${actions(button('Check connection',"state.configured=true;state.notice='Sample connection ready';go(state.onboarding?'setup-workspace':activeScenario==='expired'?'chat':'agents')",true),button('Show authentication failure',"go('auth-error')"))}`)}
function capabilityScreen(setup=false){return screen('Phone access',`<p>Enable the capabilities you want. You can skip optional access and return later.</p>${Object.entries(state.capabilities).map(([name,granted])=>row(name,granted?'Enabled in sample':'Optional · Not enabled',name==='Accessibility'?"go('accessibility')":name==='Location'?"go('permission-request')":"state.permissionName='Notifications';go('android-special')",granted?'ready':'off')).join('')}${row('Screen capture','Consent is requested for each capture',"go('capture-consent')")}${actions(button(setup?'Skip optional capabilities':'Continue without optional access',setup?"go('ready')":"go('chat')",true))}`)}
function permissionResult(granted){const name=state.permissionName||'Location';state.capabilities[name]=granted;if(granted){state.notice=`${name} enabled in the sample.`;go(state.onboarding?'setup-access':'phone-access')}else go('permission-denied')}
function mainBody(){const setup=setupBody();if(setup!==null)return setup;if(['chat','draft','working','needs-you','done','stopped','keyboard'].includes(view))return chat();switch(view){case'history':return historyView();case'workspaces':return screen('Workspaces',state.workspaces.map(w=>row(w,`${state.sessions.filter(s=>s.workspace===w).length} conversations`,`selectWorkspace(${JSON.stringify(w)})`)).join('')+actions(button('Create workspace',"go('create-workspace')",true),button('Workspace details',"go('workspace-details')")));case'external-folder':case'folder-lost':return screen(view==='folder-lost'?'Restore folder access':'Connect Android folder',`<p>${view==='folder-lost'?'The selected folder is unavailable. Your saved conversations are still here.':'Choose an existing shared-storage folder or a visible Olea folder.'}</p>${info('Design preview: direct agent working-directory support is not yet validated.')}${actions(button(view==='folder-lost'?'Restore access':'Choose folder',"go('folder-picker')",true),button('Use managed workspace instead',"go('create-workspace')"))}`);case'folder-picker':return screen('Choose a folder',`<p>Internal shared storage</p>${row('Olea','/storage/emulated/0/Olea',"state.form.folder='Olea';render()")}${row('Documents','/storage/emulated/0/Documents',"state.form.folder='Documents';render()")}${info('Selected: '+(state.form.folder||'Olea'))}${actions(button('Use this folder',"state.notice='Sample folder selected. Direct workspace support remains unverified.';go(state.onboarding?'setup-access':'workspace-details')",true),button('Cancel','back()'))}`,true);case'workspace-details':return screen(state.workspace,`${info(state.notice||'Managed workspace · /workspace/'+state.workspace.toLowerCase())}${row('Files','Browse workspace files',"go('files')")}${row('Terminal','Workspace shell sessions',"go('terminal')")}${row('Conversations','Saved sessions for this workspace',`selectWorkspace(${JSON.stringify(state.workspace)})`)}`);case'files':return screen('Workspace files',`${['projects/','overview.md','README.md'].map(f=>row(f,'Sample workspace content',f.endsWith('/')?"state.file='projects/reading-view.md';go('file-preview')":`state.file='${f}';go('file-preview')`)).join('')}`);case'file-preview':return screen(state.file,`<div class="infoBox"><b>Project overview</b><p>Reading view: ready to review.</p><p>Login redirect: needs inspection.</p></div>${actions(button('Back to files',"go('files')"))}`);case'agents':return screen('Agents',`<p>Add or configure agents independently.</p>${['Pi','Codex','Claude Code'].map((a,i)=>row(a,i===0||state.agent===a?'Sample configuration available':'Not installed',`state.agent='${a}';go('agent-config')`,i===0||state.agent===a?'ready':'off')).join('')}`);case'providers':return screen('Providers',`<p>Connections are used only where an agent supports them. Other agents may use their own login.</p>${state.connections.map(n=>row(n,'Fictitious connection',"go('provider-edit')")).join('')}${actions(button('Add connection',"go('provider-edit')",true))}`);case'provider-edit':return screen('Sample connection',`${field('Display name','providerName','Sample connection')}${field('Endpoint','endpoint','https://provider.example.invalid')}${info('No real keys are needed or stored by this demo.')}${actions(button('Save sample connection',"state.connections.push(state.form.providerName||'New sample connection');go('providers')",true))}`);case'expired':return screen('Authentication expired',info('This agent needs to reconnect. Saved messages are unchanged.',true)+actions(button('Reconnect',"go('agent-config')",true),button('View saved conversation',"go('chat')")));case'phone-access':return capabilityScreen();case'permission-request':return screen('Location is needed',`<p>This task asks for your location. You skipped it during setup.</p>${actions(button('Open Android permission',"state.permissionName='Location';go('android-permission')",true),button('Continue without location',"go('permission-denied')"))}`);case'android-permission':return screen('Allow Olea to access location?',`<p>You control this permission in Android.</p>${actions(button('Allow while using',"permissionResult(true)",true),button('Don’t allow',"permissionResult(false)"))}`,true);case'permission-denied':return screen('Location not enabled',`<p>You can continue other work without location.</p>${actions(button('Continue without location',"go(state.onboarding?'setup-access':'chat')",true),button('Try permission again',"go('permission-request')"))}`);case'accessibility':return screen('Accessibility access',`<p>Enable Olea in Android Accessibility settings to inspect and interact with exposed app controls.</p>${actions(button('Open Android settings',"state.permissionName='Accessibility';go('android-special')",true),button('Not now','back()'))}`);case'android-special':return screen(state.permissionName==='Notifications'?'Notification access':'Accessibility · Olea',`<p>This special access is controlled separately in Android.</p>${actions(button('Enable sample service',"permissionResult(true)",true),button('Keep disabled',"permissionResult(false)"))}`,true);case'revoked':return screen('Access was revoked',info('Accessibility was disabled in Android. The current task needs it to continue.',true)+actions(button('Restore access',"go('accessibility')",true),button('Keep conversation open',"go('chat')")));case'capture-consent':return screen('Capture your screen',`<p>Android asks for consent when capture is requested.</p>${actions(button('Request capture',"go('android-capture')",true),button('Not now','back()'))}`);case'android-capture':return screen('Start recording or casting?',`<p>Olea will capture the sample screen for this request.</p>${actions(button('Start now',"state.capture=true;go('capture-result')",true),button('Cancel','back()'))}`,true);case'capture-result':return screen('Capture complete',`<div class="capturePreview">Sample Android screen<br>Capture finished</div>${info('Capture ended. A later capture requires its own consent.')}${actions(button('Return to conversation',"state.capture=false;state.notice='Sample capture attached to this task.';go('chat')",true))}`);case'environment':return screen('Environment',`${info(state.environment?'Environment · Ready':'Environment · Stopped')}${row('Sessions',`${state.sessions.filter(s=>s.status==='working').length} working · messages saved`,"go('history')")}${actions(button(state.environment?'Stop environment':'Start environment',state.environment?"go('environment-stop')":"restartEnvironment()",true),button('Diagnostics',"go('diagnostics')"))}`);case'environment-stop':return screen('Stop the environment?',`<p>This stops the shared runtime. Active turns and shell sessions will be interrupted. Saved messages remain.</p>${actions(button('Stop environment',"shutdownEnvironment()",true),button('Keep running','back()'))}`);case'startup-error':return screen('Couldn’t start environment',info('The sample runtime did not start. Your files and saved messages remain.',true)+actions(button('Retry startup',"restartEnvironment()",true),button('View diagnostics',"go('diagnostics')")));case'diagnostics':return screen('Diagnostics',`<pre class="infoBox">Sample runtime check\nStorage: available\nBootstrap: interrupted\nNo real device inspection</pre>${actions(button('Retry startup','restartEnvironment()',true))}`);case'environment-lost':return screen('Environment interrupted',info('Android may end background processes. Saved conversations are available; the previous turn will not run again automatically.',true)+actions(button('Start environment','restartEnvironment()',true),button('View saved messages',"go('chat')")));case'app-away':case'locked':return screen(view==='locked'?'Sample lock screen':'Another app',`<p>${view==='locked'?'The phone was locked.':'Olea is in the background in this sample.'}</p>${info('This fixture illustrates returning, not a guarantee that Android keeps the runtime alive.')}${actions(button(view==='locked'?'Unlock sample phone':'Return to Olea',"go('chat')",true),button('Show environment interruption',"state.environment=false;go('environment-lost')"))}`,true);case'settings':return screen('Settings',`<p>When Olea opens</p>${['last','fresh'].map(v=>`<label class="choiceRow"><input type="radio" name="launch" ${state.launch===v?'checked':''} onchange="state.launch='${v}'"><span>${v==='last'?'Resume last active session':'Open a fresh chat'}</span></label>`).join('')}${info('After setup. Changing this preference does not stop active sessions.')}`);case'about':return screen('Olea',`<p>Agents on your phone.</p>${info('Browser design reference · Sample build')}${row('Licenses','Original Olea code: MIT',"go('licenses')")}`);case'licenses':return screen('Licenses',`<p>Original Olea code is licensed under MIT. Third-party components retain their own licenses.</p>${info('The production app will list the components it actually includes.')}`);case'error':case'tool-error':case'uncertain':return recoveryScreen();case'terminal-new':return screen('Terminal sessions',`${info('Workspace: '+state.workspace)}${state.shells.map((s,i)=>row(s.name,'Sample shell',`state.shell=${i};go('terminal')`)).join('')}${actions(button('New shell',"newShell()",true))}`);case'terminal-lost':return screen('Shell disconnected',info('The environment ended. Previous output is retained as history, not as proof the process is still running.',true)+actions(button('Start environment',"restartTerminal()",true)));default:if(isTerminal())return terminal();return screen('Return to your task',actions(button('Open conversation',"go('chat')",true)))}}
function recoveryScreen(){const uncertain=view==='uncertain',tool=view==='tool-error';return screen(uncertain?'Result not confirmed':tool?'Tool failed':'Connection lost',`${info(uncertain?'The connection ended before the result was confirmed. Inspect the actual result before repeating the action.':tool?'Reading projects/missing.md failed. The result remains in the transcript.':'The reply was interrupted. Saved messages remain; the previous task has not restarted.',true)}<details class="tools"><summary>Last tool result</summary><pre>${uncertain?'No confirmed completion received.':tool?'ENOENT: projects/missing.md':'Last confirmed operation: read workspace notes.'}</pre></details>${actions(button(uncertain?'Check result first':tool?'Ask agent to inspect':'Review and continue',`answer('${uncertain?'Inspect the result before repeating the action.':tool?'Inspect the missing file without changing other files.':'Review the last result and tell me what remains.'}')`,true),button('View saved messages',"go('chat')"))}`)}
function restartTerminal(){state.environment=true;state.workspaceShells={};state.shellWorkspace=state.workspace;state.shells=[{name:'Shell 1',output:'New sample shell\n'+workspacePath()+' $ ',running:false}];state.shell=0;go('terminal')}
function restartEnvironment(){state.environment=true;state.workspaceShells={};state.shellWorkspace=state.workspace;state.shells=[{name:'Shell 1',output:'New sample shell after runtime restart\n'+workspacePath()+' $ ',running:false}];state.shell=0;state.notice='Environment restarted. No prior turn was replayed.';state.sessions.filter(s=>s.status==='working').forEach(s=>s.status='error');go('environment')}
function shutdownEnvironment(){state.environment=false;state.sessions.filter(s=>s.status==='working').forEach(s=>s.status='error');state.shells.forEach(s=>s.running=false);go('environment')}
function isTerminal(){return ['terminal','terminal-switch','terminal-running','terminal-close'].includes(view)}
function workspacePath(){return '/workspace/'+state.workspace.toLowerCase().replace(/\s+/g,'-')}
function ensureShellWorkspace(){if(state.shellWorkspace===state.workspace)return;state.workspaceShells[state.shellWorkspace]={shells:state.shells,shell:state.shell};const saved=state.workspaceShells[state.workspace];state.shells=saved?.shells||[{name:'Shell 1',output:workspacePath()+' $ ',running:false}];state.shell=saved?.shell||0;state.shellWorkspace=state.workspace}
function newShell(){ensureShellWorkspace();state.shells.push({name:'Shell '+(state.shells.length+1),output:workspacePath()+' $ ',running:false});state.shell=state.shells.length-1;go('terminal')}
function terminal(){ensureShellWorkspace();const s=state.shells[state.shell];if(!state.environment)return screen('Terminal unavailable',actions(button('Start environment',"go('terminal-lost')",true)));return `<div class="terminalTabs"><select aria-label="Terminal session" onchange="state.shell=Number(this.value);render()">${state.shells.map((s,i)=>`<option value="${i}" ${state.shell===i?'selected':''}>${E(s.name)}</option>`).join('')}</select>${button('＋','newShell()')}${button('Close shell',"sheet='close-shell';render()")}</div><div class="terminalBody" id="terminalOutput">${E(s.output)}${s.running?'\nSample command running…':''}</div><form class="terminalInput" onsubmit="event.preventDefault();runCommand()"><span>$</span><input id="terminalCommand" aria-label="Terminal command" placeholder="Try pwd or ls" value="${E(state.form.command||'')}" oninput="state.form.command=this.value">${button(s.running?'Interrupt':'Run',s.running?'interruptShell()':'runCommand()')}</form><div class="extraKeys">${['Esc','Ctrl','Tab','←','↓','↑','→'].map(k=>button(k,`extraKey('${k}')`)).join('')}${button(state.keyboard?'⌄':'⌨','state.keyboard=!state.keyboard;render()')}</div>${state.keyboard?keyboard():''}`}
function runCommand(){const s=state.shells[state.shell],cmd=(state.form.command||'').trim();if(!cmd||s.running)return;state.lastCommand=cmd;const output=cmd==='pwd'?workspacePath():cmd==='ls'?'README.md  overview.md  projects/':cmd.startsWith('echo ')?cmd.slice(5):cmd==='clear'?'':cmd==='sleep 10'?'':`Sample terminal: ${cmd}\nNo command was executed.`;s.output=cmd==='clear'?'':s.output+'\n$ '+cmd+'\n'+output+'\n';s.running=cmd==='sleep 10';state.form.command='';render()}
function interruptShell(){const s=state.shells[state.shell];s.running=false;s.output+='\n^C\n'+workspacePath()+' $ ';state.ctrl=false;render()}
function extraKey(key){const input=document.getElementById('terminalCommand');if(key==='Ctrl'){state.ctrl=!state.ctrl;render()}else if(key==='Esc'){state.form.command='';render()}else if(key==='Tab'){state.form.command='overview.md';render()}else if(key==='←'||key==='→'){input.focus();const pos=Math.max(0,Math.min(input.value.length,input.selectionStart+(key==='←'?-1:1)));input.setSelectionRange(pos,pos)}else if(key==='↑'){state.form.command=state.lastCommand||'pwd';render()}else if(key==='↓'){state.form.command='';render()}}
function closeShell(){state.shells.splice(state.shell,1);state.shell=Math.max(0,state.shells.length-1);sheet='';if(!state.shells.length)go('terminal-new');else render()}
function drawerUI(){return `<div class="drawerScrim" onclick="drawer=false;render()"><nav class="drawer" aria-label="App menu" onclick="event.stopPropagation()"><h2>Olea</h2>${[['Agents','agents'],['Providers','providers'],['Environment','environment'],['Phone access','phone-access']].map(([t,v])=>button(t,`go('${v}')`)).join('')}<hr>${button('Settings',"go('settings')")}${button('About',"go('about')")}</nav><button class="drawerClose" aria-label="Close app menu" onclick="drawer=false;render()">×</button></div>`}
function sheetUI(){return `<div class="sheetScrim" onclick="sheet='';render()"><section class="sheet" onclick="event.stopPropagation()"><h2>${sheet==='close-shell'?'Close this shell?':'Conversation details'}</h2>${sheet==='close-shell'?`<p>End ${E(state.shells[state.shell]?.name||'the shell')}. Leaving the terminal view is a separate action.</p>${actions(button('End shell','closeShell()',true),button('Keep shell',"sheet='';render()"))}`:`<p>${E(state.current===null?state.workspace:currentSession().workspace)}</p>${row('Workspace details','Location and workspace tools',"go('workspace-details')")}${row('Files','Browse on demand',"go('files')")}${row('Terminal','Workspace shell sessions',"go('terminal')")}${button('Close',"sheet='';render()")}`}</section></div>`}
function render(){instructions();const serial=++screenSerial;const body=mainBody();document.getElementById('phone').innerHTML=`<div class="status"><span>9:41</span><span>Wi-Fi · 86%</span></div>${header()}${body}${!state.onboarding&&!isTerminal()&&!['folder-picker','android-permission','android-special','android-capture','locked','app-away'].includes(view)?`<nav class="bottom" aria-label="Olea destinations">${button('Conversations',"state.search='';go('history')")}${button('Workspaces',"go('workspaces')")}</nav>`:''}<div class="phoneBack" aria-hidden="true"><div class="handle"></div></div>${drawer?drawerUI():''}${sheet?sheetUI():''}`;document.getElementById('screenCaption').textContent=`Viewing: ${view} · Sample behavior`;document.querySelectorAll('#phone .stateChip').forEach(e=>e.style.flex='none');requestAnimationFrame(()=>{if(serial!==screenSerial)return;const log=document.getElementById('terminalOutput');if(log)log.scrollTop=log.scrollHeight});fitPhone()}
function fitPhone(){const stage=document.querySelector('.phoneStage');if(!stage)return;const scale=Math.max(0,Math.min(stage.clientWidth/390,stage.clientHeight/780,1.15));const wrap=document.querySelector('.phonewrap');wrap.style.width=390*scale+'px';wrap.style.height=780*scale+'px';document.getElementById('phone').style.transform=`scale(${scale})`}
// Input focus opens the browser keyboard fixture; Android owns the real keyboard.
document.addEventListener('focusin',event=>{if(event.target.id!=='messageInput'||state.keyboard)return;const start=event.target.selectionStart,end=event.target.selectionEnd;state.keyboard=true;state.providerMenu=false;render();const input=document.getElementById('messageInput');input.focus();input.setSelectionRange(start,end)});
document.addEventListener('click',event=>{if(!state.providerMenu||event.target.closest('#providerMenu,#providerToggle'))return;state.providerMenu=false;document.getElementById('providerMenu')?.remove();const toggle=document.getElementById('providerToggle');toggle?.setAttribute('aria-expanded','false');toggle?.removeAttribute('aria-controls')});
// Escape simulates Android Back in the browser; terminal shortcuts also work.
document.addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();back()}if(isTerminal()&&(event.ctrlKey||state?.ctrl)&&event.key.toLowerCase()==='c'){event.preventDefault();interruptShell()}});
new ResizeObserver(fitPhone).observe(document.querySelector('.phoneStage'));
const initialKey=scenarios.some(s=>s.key===location.hash.slice(1))?location.hash.slice(1):'chat';activeJourney=scenarios.find(s=>s.key===initialKey).area;seed(initialKey);renderBoard();startScenario(initialKey);
